const { withGradleProperties } = require('expo/config-plugins');

/**
 * Keep release builds readable and R8-free.
 *
 * WorkManager and Room (pulled in by expo-background-task / expo-notifications)
 * crash at startup when R8 strips classes referenced only from the Android
 * manifest. ExoPlayer and react-native-google-mobile-ads also rely on
 * reflection. For a sideloaded educational build, size is not worth the risk.
 *
 * `android/` is generated by Continuous Native Generation, so the setting has
 * to live in a config plugin rather than in gradle.properties directly.
 */
const PROPERTIES = {
  'android.enableMinifyInReleaseBuilds': 'false',
  'android.enableShrinkResourcesInReleaseBuilds': 'false',
};

module.exports = function withReleaseBuild(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(PROPERTIES)) {
      const entry = cfg.modResults.find(
        (item) => item.type === 'property' && item.key === key,
      );
      if (entry) {
        entry.value = value;
      } else {
        cfg.modResults.push({ type: 'property', key, value });
      }
    }
    return cfg;
  });
};
